(()=>{'use strict';const D=window.FOLLOWUP,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let id='T40',round=7,view='case';
$('.tabs').insertAdjacentHTML('afterbegin','<button data-view="case" aria-pressed="false">Explain this case</button><button data-view="plots" aria-pressed="false">Raw plots & map</button>');
const labels={exposure_candidate:'Candidate peer uptake',own_continuation:'Own continuation',shared_common_rule:'Shared or common rule',game_experience_candidate:'Candidate game-experience link'};
function highlight(t,q){if(!q||!t.includes(q))return esc(t);const i=t.indexOf(q);return esc(t.slice(0,i))+'<mark>'+esc(q)+'</mark>'+esc(t.slice(i+q.length));}
function card(title,meta,t,q){return `<article class="card"><h3>${esc(title)}</h3><div class="tag">${esc(meta)}</div><div class="myth">${highlight(t||'No text available for this round.',q)}</div></article>`;}
function navigate(next,n){id=next;round=n;render();}
const colors={exposure_candidate:'#245cc5',own_continuation:'#7056a3',shared_common_rule:'#8b6b28',game_experience_candidate:'#15766b'};
const num=v=>typeof v==='number'&&Number.isFinite(v);
function playPlot(t,role,max,color){
 const W=850,H=250,x=n=>64+(n-1)*80,y=v=>190-v/max*135,rows=t.rounds.filter(r=>r.game[role]===t.agent),field=role==='investor'?'sent':'returned';
 const mythX=x(round)+(t.task_order==='game_myth'?19:-19);
 let g=`<rect x="${x(round)-34}" y="35" width="68" height="155" fill="#f0f4fc"/>`;
 for(let i=0;i<=5;i++){const v=max*i/5;g+=`<line x1="55" x2="805" y1="${y(v)}" y2="${y(v)}" stroke="#dae3ef"/><text x="43" y="${y(v)+5}" text-anchor="end">${v}</text>`;}
 for(const r of t.rounds){g+=`<text x="${x(r.round)}" y="219" text-anchor="middle">${r.round}</text>`;if(!rows.includes(r))g+=`<text x="${x(r.round)}" y="186" text-anchor="middle" fill="#8996a8">–</text>`;}
 // Points only: do not interpolate across receiver/sender turns or absent decisions.
 for(const r of rows){const v=r.game[field];if(!num(v))continue;g+=`<g role="button" tabindex="0" data-plot-round="${r.round}" aria-label="Round ${r.round}, ${role==='investor'?'own send':'own return'} ${v}"><circle cx="${x(r.round)}" cy="${y(v)}" r="9" fill="${color}"/><title>Round ${r.round}: ${v}</title><text x="${x(r.round)}" y="${y(v)-16}" text-anchor="middle" fill="${color}">${Number(v.toFixed(2))}</text></g>`;}
 for(const e of D.events.filter(e=>e.id===t.id)){const xx=x(e.event_round)+(t.task_order==='game_myth'?19:-19);g+=`<path d="M${xx-5},29 L${xx},21 L${xx+5},29 Z" fill="${colors[e.original_event.source_assessment]}"><title>Selected change, myth round ${e.event_round}</title></path>`;}
 g+=`<line x1="${mythX}" x2="${mythX}" y1="34" y2="195" stroke="#ad4561" stroke-width="2" stroke-dasharray="5 4"/><text x="425" y="244" text-anchor="middle">Game round · click a point to inspect</text>`;
 return `<div class="plot-scroll"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${role==='investor'?'Own sending':'Own returning'} across ten game rounds; selected myth is offset to show task order">${g}</svg></div>`;
}
function sourcePlot(e){if(!e)return '<p class="hint">Choose a marked event to compare its quoted clause with possible sources.</p>';
 const best=Math.max(...e.all_earlier_own_matches.map(x=>x.longest_tokens));
 const bars=[['Previous own',e.previous_own_match.longest_tokens,'#7056a3'],['Any earlier own (maximum)',best,'#7056a3'],['Actually exposed peer',e.exposed_match.longest_tokens,'#245cc5'],['Matched unseen',e.unseen_match.longest_tokens,'#8b6b28']];
 const max=Math.max(1,...bars.map(x=>x[1])),scale=390/max;
 return `<div class="plot-scroll"><svg viewBox="0 0 850 225" role="img" aria-label="Longest contiguous token matches, not semantic or causal similarity">${bars.map(([name,v,c],i)=>`<text x="255" y="${39+i*43}" text-anchor="end">${name}</text><rect x="275" y="${20+i*43}" width="${v*scale}" height="27" rx="3" fill="${c}"/><text x="${285+v*scale}" y="${39+i*43}">${v}</text>`).join('')}<text x="425" y="215" text-anchor="middle">Longest exact consecutive match · tokens</text></svg></div>`;
}
function plots(t,e){return `<div class="stack"><article class="card"><h3>Play and myth timing</h3><p class="hint">Blue points: this agent sends (0–5). Teal points: this agent returns (0–15). Dashes mean the agent had the other role, not a zero action. Actual transfers, not perceived values.</p><div class="plot-legend"><span class="myth-key">Dashed rose line: selected myth</span><span>Triangles: selected textual changes</span></div><p class="hint">${t.task_order==='game_myth'?'Game comes first: the myth marker is just after that round’s action.':'Myth comes first: the myth marker is just before that round’s action.'} Offsets show ordering, not elapsed time. Other myths are still written each round.</p><h4>Own sends</h4>${playPlot(t,'investor',5,'#245cc5')}<h4>Own returns</h4>${playPlot(t,'trustee',15,'#15766b')}<button id="plot-behavior">Inspect behavioral eligibility</button></article><article class="card"><h3>Which source shares the wording?</h3>${sourcePlot(e)}<p class="hint">Only the selected after-quote is compared. A longer exact match is not proof of influence; paraphrases can score low or zero. “Any earlier own” includes the previous myth and has more text to match against.</p><button id="plot-sources">Read the source passages</button></article><article class="card"><h3>Where were changes selected?</h3><p class="hint">Click a cell to inspect that trajectory and round. Colored cells are the 44 selected examples—not every change. Empty cells mean “not selected,” not “no change.”</p><div class="plot-legend">${Object.entries(labels).map(([k,v])=>`<span><i style="background:${colors[k]}"></i>${esc(v)}</span>`).join('')}</div><div class="event-map" role="group" aria-label="Selected events by trajectory and round"><div class="map-row map-head"><span>Trajectory / round</span>${Array.from({length:10},(_,i)=>`<span>${i+1}</span>`).join('')}</div>${D.trajectories.map(a=>`<div class="map-row"><span class="map-name">${a.id} · ${esc(a.family)}<small>${a.tier} · ${a.size} agents · ${a.task_order==='game_myth'?'game first':'myth first'}</small></span>${a.rounds.map(r=>{const ev=D.events.find(e=>e.id===a.id&&e.event_round===r.round),desc=ev?labels[ev.original_event.source_assessment]:'No selected event';return `<button data-map-id="${a.id}" data-map-round="${r.round}" title="${a.id} round ${r.round}: ${esc(desc)}" aria-label="${a.id} round ${r.round}: ${esc(desc)}" ${ev?`style="background:${colors[ev.original_event.source_assessment]};color:white"`:''} class="${a.id===id&&r.round===round?'map-selected':''}">${ev?'●':'·'}</button>`;}).join('')}</div>`).join('')}</div></article></div>`;}
$('#trajectory').innerHTML=D.trajectories.map(t=>`<option value="${t.id}">${t.id} · ${esc(t.family)} · ${t.tier}</option>`).join('');
$('#trajectory').onchange=e=>navigate(e.target.value,1);$('#events').onchange=e=>navigate(id,Number(e.target.value));
document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{const [t,n]=b.dataset.jump.split(':');view='case';navigate(t,Number(n));});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});
function render(){const t=D.trajectories.find(t=>t.id===id),r=t.rounds[round-1],event=D.events.find(e=>e.id===id&&e.event_round===round),o=event?.original_event;
document.body.classList.toggle('guided',view==='case');
document.querySelectorAll('[data-jump]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.jump===id+':'+round)));
$('#trajectory').value=id;const events=D.events.filter(e=>e.id===id);$('#events').innerHTML=`<option value="${round}">${o?'Current selected change':'Round '+round+' · no selected event'}</option>`+events.filter(e=>e.event_round!==round).map(e=>`<option value="${e.event_round}">Round ${e.event_round} · ${esc(labels[e.original_event.source_assessment])}</option>`).join('');
$('#meta').textContent=`${t.tier==='frontier'?'Main frontier':'September'} · ${t.family} · ${t.size} agents · ${t.mixed?'mixed group':'single-model group'} · ${t.task_order==='game_myth'?'game then myth':'myth then game'}`;
$('#title').textContent=`${id} · Round ${round}`;$('#rounds').innerHTML=t.rounds.map(r=>`<button data-round="${r.round}" aria-label="Round ${r.round}" aria-pressed="${r.round===round}">${r.round}</button>`).join('');document.querySelectorAll('[data-round]').forEach(b=>b.onclick=()=>navigate(id,Number(b.dataset.round)));
document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));
$('#verdict').innerHTML=o?`<h3>${esc(labels[o.source_assessment])}</h3><p>${esc(o.source_reason)}</p><span class="badge">Provisional machine interpretation · not a causal verdict</span>`:'<h3>Read the complete trajectory</h3><p>No change event was selected here. That does not mean the story contains no rule or no change.</p>';
if(view==='case'){$('#title').textContent=window.GUIDES[id+':'+round]?.title||`${id} · Round ${round}`;$('#meta').textContent=`${id} · Round ${round} · `+$('#meta').textContent;$('#content').innerHTML=window.guidedView(t,event,esc);document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>{view=b.dataset.inspect;render();$('#title').scrollIntoView();});document.querySelectorAll('[data-evidence-round]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.evidenceRound);$('#story-heading').textContent=`${id} · Own story, round ${n}`;$('#story-note').textContent=b.dataset.evidenceNote||'';$('#story-body').innerHTML=highlight(t.rounds[n-1].own,b.dataset.evidenceQuote);$('#story-dialog').showModal();});if($('#close-story'))$('#close-story').onclick=()=>$('#story-dialog').close();}
if(view==='sources'){$('#content').innerHTML=(o?`<article class="card"><h3>The selected change</h3><blockquote>${esc(o.after_quote)}</blockquote><p class="hint"><strong>Condition:</strong> ${esc(o.condition)}<br><strong>Action:</strong> ${esc(o.action)}<br><strong>Exception / recovery:</strong> ${esc(o.exception_or_recovery)}</p><details><summary>Earlier comparison and exact-match diagnostics</summary><p>Selected earlier quote, round ${o.before_round}:</p><blockquote>${esc(o.before_quote)}</blockquote><p>Longest consecutive token match to the new quote: previous own ${event.previous_own_match.longest_tokens}; exposed peer ${event.exposed_match.longest_tokens}; unseen comparison ${event.unseen_match.longest_tokens}. These counts do not measure semantic equivalence.</p></details></article><br>`:'')+`<div class="grid">${card('Current own myth',`Round ${round}`,r.own,o?.after_quote)}${card('Previous own myth',round>1?`Round ${round-1}`:'No earlier own myth',t.rounds[round-2]?.own,o?.before_round===round-1?o.before_quote:null)}${card('Actually shown peer myth',r.exposed?`${r.exposed.family} · source round ${r.exposed.round}`:'No exposure',r.exposed?.text,o?.exposed_quote)}${card('Matched unseen myth','Different run · comparison, not an exposure',r.unseen?.text,o?.unseen_quote)}</div>`;}
if(view==='trajectory'){$('#content').innerHTML='<div class="stack">'+t.rounds.map(x=>{const e=D.events.find(e=>e.id===id&&e.event_round===x.round);return card(`Round ${x.round}`,e?labels[e.original_event.source_assessment]:'No selected event; not evidence of no change',x.own,e?.original_event.after_quote);}).join('')+'</div>';}
if(view==='behavior'){const screen=D.screens.find(x=>x.id===id&&x.round===round),amount=D.amounts.find(x=>x.id===id&&x.event_round===round);$('#content').innerHTML=`<article class="card"><h3>What happens before the story?</h3><p class="hint">${t.task_order==='game_myth'?`Round ${round}'s game happens BEFORE this myth. It can inform the story, not be caused by it. The immediate post-writing game is round ${round+1}.`:`This myth is written BEFORE round ${round}'s game. The most recent game was round ${round-1}.`} The clean test window ends at the next own myth.</p><h3>Behavioral eligibility</h3>${screen?screen.tests.map(x=>`<p><strong>${esc(x.test.replaceAll('_',' '))}:</strong> ${esc(x.reason||'Explicit amount candidate; see timing result below.')}</p>`).join(''):'<p>No selected rule event was screened at this round.</p>'}${amount?`<p>${esc(amount.reason)}</p>${amount.eligible?`<div class="facts"><span>Named amount: ${amount.target}</span><span>Previous send: ${amount.prior_send} (R${amount.prior_sender_round})</span><span>Next send: ${amount.next_send} (R${amount.active_game_round})</span></div><p>Already at target before writing. This case does not demonstrate a change caused by the rule.</p>`:''}`:''}<p class="hint">An ambiguous or unobserved trigger is not a failed behavioral prediction. Actual transfers below are descriptive outcomes, not necessarily what the agent perceived.</p></article><br><article class="card"><h3>Game timeline for this agent</h3><div class="table-wrap"><table><thead><tr><th>Round</th><th>Own role</th><th>Actual send</th><th>Actual return</th><th>Recorded communicated send</th><th>Recorded communicated return</th></tr></thead><tbody>${t.rounds.map(x=>`<tr class="${x.round===round?'selected-row':''}"><td>${x.round}</td><td>${x.game.investor===t.agent?'Sender':'Receiver'}</td><td>${esc(x.game.sent)}</td><td>${esc(x.game.returned)}</td><td>${esc(x.game.sent_communicated??'Not recorded')}</td><td>${esc(x.game.returned_communicated??'Not recorded')}</td></tr>`).join('')}</tbody></table></div></article>`;}
if(view==='plots'){$('#content').innerHTML=plots(t,event);$('#plot-behavior').onclick=()=>{view='behavior';render();};$('#plot-sources').onclick=()=>{view='sources';render();};document.querySelectorAll('[data-plot-round]').forEach(p=>{p.onclick=()=>navigate(id,Number(p.dataset.plotRound));p.onkeydown=k=>{if(k.key==='Enter'||k.key===' '){k.preventDefault();p.onclick();}};});document.querySelectorAll('[data-map-id]').forEach(b=>b.onclick=()=>{navigate(b.dataset.mapId,Number(b.dataset.mapRound));$('#title').scrollIntoView({block:'start'});});}
history.replaceState(null,'',`#${id}:${round}:${view==='plots'?'diagnostics':view}`);}
const parts=location.hash.slice(1).split(':');if(D.trajectories.some(t=>t.id===parts[0])){id=parts[0];round=Math.max(1,Math.min(10,Number(parts[1])||1));if(['sources','trajectory','behavior','case'].includes(parts[2]))view=parts[2];if(parts[2]==='diagnostics')view='plots';}render();})();
